@import url('https://fonts.googleapis.com/css2?family=Mulish:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* WhatsApp DNA — chat wallpaper beige, teal headers, bubble green, thumb-first */
.theme-whatsapp-dna {
  --bg: oklch(0.936 0.010 84);
  --surface: oklch(1.000 0 0);
  --surface-2: oklch(0.939 0.012 79.8);
  --fg: oklch(0.215 0.019 235.1);
  --fg-muted: oklch(0.559 0.025 233.7);
  --accent: oklch(0.535 0.102 174.2);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.761 0.201 149.7);
  --line: oklch(0.895 0.013 86.8);
  --success: oklch(0.761 0.201 149.7);
  --warning: oklch(0.768 0.158 81.3);
  --danger: oklch(0.647 0.187 29.3);
  --radius: 1rem;
  --radius-sm: 0.5rem;
  --radius-lg: 1.25rem;
  --radius-pill: 9999px;
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Mulish", sans-serif;
  --font-body: "Mulish", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: -0.01em;
  --label-transform: none;
  --label-tracking: 0.04em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-whatsapp-dna h1,
.theme-whatsapp-dna h2,
.theme-whatsapp-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-whatsapp-dna { background-image: radial-gradient(oklch(0.5 0.03 160 / 6%) 1.5px, transparent 1.5px); background-size: 18px 18px; }
.theme-whatsapp-dna { --font-ui: var(--font-display); }
.theme-whatsapp-dna h1 { font-weight: 700; }
.theme-whatsapp-dna button { font-weight: 600; }
.theme-whatsapp-dna { border-top: 5px solid #008069; }
.theme-whatsapp-dna h1 { color: #008069; }

/* depth */
.theme-whatsapp-dna thead th { background: oklch(0.97 0.008 84); font-size: 0.8em; font-weight: 700; color: var(--accent); border-bottom: 1px solid var(--line); }
.theme-whatsapp-dna td { border-bottom: 1px solid var(--line); }
.theme-whatsapp-dna tbody tr:hover { background: oklch(0.95 0.01 84); }
.theme-whatsapp-dna a { color: var(--accent); font-weight: 600; text-decoration: none; }
.theme-whatsapp-dna a:hover { text-decoration: underline; }
.theme-whatsapp-dna input, .theme-whatsapp-dna select { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius-pill); }
.theme-whatsapp-dna textarea { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius-lg); }
.theme-whatsapp-dna input:focus-visible, .theme-whatsapp-dna textarea:focus-visible, .theme-whatsapp-dna select:focus-visible { outline: none; border-color: var(--accent); box-shadow: var(--glow); }
.theme-whatsapp-dna kbd { font-family: var(--font-body); font-size: 0.85em; background: oklch(0.93 0.055 150); border-radius: 0.5rem; padding: 0.1em 0.5em; }
.theme-whatsapp-dna ::selection { background: oklch(0.88 0.09 150); }
.theme-whatsapp-dna ::-webkit-scrollbar { width: 8px; height: 8px; }
.theme-whatsapp-dna ::-webkit-scrollbar-track { background: transparent; }
.theme-whatsapp-dna ::-webkit-scrollbar-thumb { background: oklch(0.75 0.02 84); border-radius: 4px; }
.theme-whatsapp-dna .label-caps { color: var(--accent); font-weight: 700; }
.theme-whatsapp-dna div.themed-border { background: oklch(0.93 0.055 150 / 60%); border-radius: var(--radius-lg); border-bottom-right-radius: 0.25rem; } /* sent-bubble — div only: must not clobber chip/button fills */
.theme-whatsapp-dna span.bg-success { color: oklch(0.25 0.06 150); } /* light bubble green needs dark text */
.theme-whatsapp-dna h2::after { content: " ✓✓"; font-size: 0.6em; vertical-align: 0.25em; color: oklch(0.72 0.11 220); } /* read receipt */
.theme-whatsapp-dna button:active { transform: scale(0.97); }

/* alt mode: WhatsApp dark — deep blue-teal #0B141A wallpaper, #00A884 bubble green */
.theme-whatsapp-dna.alt-mode {
  --bg: oklch(0.17 0.015 230);
  --surface: oklch(0.21 0.015 230);
  --surface-2: oklch(0.25 0.02 230);
  --fg: oklch(0.96 0.005 200);
  --fg-muted: oklch(0.68 0.02 220);
  --line: oklch(1 0 0 / 12%);
  --accent: oklch(0.70 0.15 165);
  --accent-fg: oklch(0.13 0 0);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  background-image: radial-gradient(oklch(1 0 0 / 3%) 1.5px, transparent 1.5px);
  background-size: 18px 18px;
  border-top-color: oklch(0.70 0.15 165);
}
.theme-whatsapp-dna.alt-mode h1 { color: oklch(0.70 0.15 165); }
.theme-whatsapp-dna.alt-mode thead th { background: oklch(0.23 0.018 230); color: var(--accent); }
.theme-whatsapp-dna.alt-mode tbody tr:hover { background: oklch(0.22 0.018 230); }
.theme-whatsapp-dna.alt-mode kbd { background: oklch(0.32 0.05 165); }
.theme-whatsapp-dna.alt-mode div.themed-border { background: oklch(0.32 0.05 165 / 50%); }
.theme-whatsapp-dna.alt-mode ::selection { background: oklch(0.40 0.08 165); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"], [class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
